using MediatR; using PamirPlastik.Application.Features.Mediator.Queries.FairQueries; using PamirPlastik.Application.Features.Mediator.Results.FairResults; using PamirPlastik.Application.Interfaces; using PamirPlastik.Domain.Entities; namespace PamirPlastik.Application.Features.Mediator.Handlers.FairHandlers { public class GetFairQueryHandler : IRequestHandler<GetFairQuery, List<GetFairQueryResult>> { private readonly IRepository<Fair> _repository; public GetFairQueryHandler(IRepository<Fair> repository) { _repository = repository; } public async Task<List<GetFairQueryResult>> Handle(GetFairQuery request, CancellationToken cancellationToken) { var values = await _repository.GetAllAsync(); return values.Select(x => new GetFairQueryResult { FairID = x.FairID, Name = x.Name, Location = x.Location, Date = x.Date, Stand = x.Stand, Img1 = x.Img1, Img2 = x.Img2, IsFuture = x.IsFuture }).ToList(); } } }
